1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// 本文件是“两个不同的成功投料请求不能指向同一条投料登记”的回归保障：
15	// 同一批次用两个不同请求编号登记内容完全相同的投料，本应得到两个连续序号；
16	// 若把第二次请求保存结果的序号改成第一次的序号、其余内容（物料、克数、
17	// 时间、登记人）保持一致，则每个请求的内容与结果单独看都能通过现有逐项
18	// 核对，批次里的两条投料也都还在、累计数量正确——但两个请求随后都会返回
19	// 第一条投料，这不能被当作两次各自成功的登记。打开台账及之后每次查询、
20	// 写入的重新读取都必须以 ErrCorruptData 拒绝整份台账，错误信息包含两个
21	// 请求编号、批次编号与重复的登记序号；不删除请求、不合并投料、不替结果
22	// 重新分配序号，被拒绝的写入不留业务记录、不占用请求编号。
23	
24	// feedingAliasBaseTime 是本文件测试使用的固定投料时间。
25	func feedingAliasBaseTime() time.Time {
26		return time.Date(2026, 10, 5, 9, 30, 0, 0, time.UTC)
27	}
28	
29	// setupFeedingAliasLedger 在 dir 建立一份正常台账并关闭：
30	//   - B1（执行中）：feed-1 与 feed-2 用完全相同的内容（M1、1.000 克、
31	//     同一时刻、同一登记人）各登记一次，分别得到序号 1、2；
32	//   - B2（执行中）：feed-b2 以完全相同的投料内容登记，得到 B2 自己的
33	//     序号 1——不同批次各自从 1 开始，即使内容相同也不属于重复指向。
34	//
35	// 返回落盘后的台账文件内容，供各用例改坏后重写。
36	func setupFeedingAliasLedger(t *testing.T, dir string) []byte {
37		t.Helper()
38		s, err := Open(dir)
39		if err != nil {
40			t.Fatalf("Open 失败: %v", err)
41		}
42		registerStandardRecipe(t, s, "recipe-1") // M1=100、M2=0.5、M3=0.010
43		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
44			t.Fatal(err)
45		}
46		if _, err := s.StartBatch("s1", "B1"); err != nil {
47			t.Fatal(err)
48		}
49		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
50			t.Fatal(err)
51		}
52		if _, err := s.StartBatch("s2", "B2"); err != nil {
53			t.Fatal(err)
54		}
55		tm := feedingAliasBaseTime()
56		// 两条内容完全相同的投料（连时间与登记人都相同），仅请求编号不同：
57		// 正常规则下它们是两次各自成功的登记，序号分别为 1 和 2。
58		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三"); err != nil {
59			t.Fatal(err)
60		}
61		if _, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", tm, "张三"); err != nil {
62			t.Fatal(err)
63		}
64		// 另一批次以相同内容登记，序号同样为 1，但指向的是 B2 自己的投料。
65		if _, err := s.AddFeeding("feed-b2", "B2", "M1", "1.000", tm, "张三"); err != nil {
66			t.Fatal(err)
67		}
68		if err := s.Close(); err != nil {
69			t.Fatal(err)
70		}
71		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
72		if err != nil {
73			t.Fatal(err)
74		}
75		return good
76	}
77	
78	// retargetFeedingRequestResult 把正常台账中指定投料请求的保存结果按 mutate
79	// 改写，返回改写后的文件内容。本文件用它把 feed-2 结果的序号从 2 改成 1。
80	func retargetFeedingRequestResult(t *testing.T, good []byte, reqNo string, mutate func(*FeedingView)) []byte {
81		t.Helper()
82		var st persistedState
83		if err := json.Unmarshal(good, &st); err != nil {
84			t.Fatal(err)
85		}
86		req := st.Requests[reqNo]
87		if req == nil {
88			t.Fatalf("正常台账中应存在 %q 请求记录", reqNo)
89		}
90		var view FeedingView
91		if err := json.Unmarshal(req.Result, &view); err != nil {
92			t.Fatal(err)
93		}
94		mutate(&view)
95		raw, err := json.Marshal(view)
96		if err != nil {
97			t.Fatal(err)
98		}
99		req.Result = raw
100		data, err := json.MarshalIndent(&st, "", "  ")
101		if err != nil {
102			t.Fatal(err)
103		}
104		return data
105	}
106	
107	// aliasFeedingResultToFirst 把 feed-2 保存结果的登记序号改成 1，其余内容
108	// （物料、克数、时间、登记人）保持不变。由于 feed-2 与 feed-1 原提交内容
109	// 完全相同，改完后 feed-2 的结果既符合自己的原提交内容，又与 B1 序号 1
110	// 的实际投料逐项一致——单请求核对全部通过，唯有“两个请求指向同一条投料”
111	// 这一跨请求关系不成立。B1 的两条投料记录与累计数量都保持原样。
112	func aliasFeedingResultToFirst(t *testing.T, good []byte) []byte {
113		t.Helper()
114		return retargetFeedingRequestResult(t, good, "feed-2", func(v *FeedingView) {
115			if v.Seq != 2 {
116				t.Fatalf("改坏前 feed-2 的结果序号应为 2，得到 %d", v.Seq)
117			}
118			v.Seq = 1
119		})
120	}
121	
122	// 打开台账时发现两个不同的成功投料请求指向同一批次的同一条投料登记，
123	// 必须返回 ErrCorruptData：错误信息说明两个请求指向了同一条投料，并包含
124	// 两个请求编号、批次编号与重复的登记序号；不返回可用对象，原文件保持不变。
125	func TestOpenRejectsTwoFeedingRequestsAliasingSameFeeding(t *testing.T) {
126		dir := t.TempDir()
127		good := setupFeedingAliasLedger(t, dir)
128		bad := aliasFeedingResultToFirst(t, good)
129		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
130			t.Fatal(err)
131		}
132	
133		s, err := Open(dir)
134		if !errors.Is(err, ErrCorruptData) {
135			t.Fatalf("两个投料请求指向同一条投料应返回 ErrCorruptData，得到 %v", err)
136		}
137		if s != nil {
138			s.Close()
139			t.Fatalf("损坏台账不应返回可用的 Store 对象")
140		}
141		msg := err.Error()
142		for _, want := range []string{"feed-1", "feed-2", "B1", "登记序号 1", "同一条投料"} {
143			if !strings.Contains(msg, want) {
144				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
145			}
146		}
147		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
148		if err != nil {
149			t.Fatal(err)
150		}
151		if !bytes.Equal(got, bad) {
152			t.Fatalf("拒绝打开不应改动台账文件")
153		}
154	}
155	
156	// 台账正常打开后文件才被改坏（feed-2 的结果序号改成 1）：下一次查询或
157	// 写入重新读取时必须返回 ErrCorruptData——即使访问的是另一个正常批次 B2
158	// 也不能绕过；被拒绝的重放不得返回第一条投料，被拒绝的新写入不留业务
159	// 记录、不占用请求编号。恢复后两个原请求分别取回各自的记录，被拒绝过的
160	// 新请求编号仍可正常使用并取得连续序号。
161	func TestFeedingRequestAliasingDetectedOnEveryReload(t *testing.T) {
162		dir := t.TempDir()
163		good := setupFeedingAliasLedger(t, dir)
164		tm := feedingAliasBaseTime()
165	
166		s, err := Open(dir)
167		if err != nil {
168			t.Fatal(err)
169		}
170		defer s.Close()
171	
172		// 打开后把 feed-2 的保存结果序号改坏，其余记录（含 B2）保持完整。
173		bad := aliasFeedingResultToFirst(t, good)
174		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
175			t.Fatal(err)
176		}
177	
178		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
179		for _, batchNo := range []string{"B1", "B2"} {
180			v, err := s.GetBatch(batchNo)
181			if !errors.Is(err, ErrCorruptData) {
182				t.Fatalf("损坏未修复时查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
183			}
184			if v != nil {
185				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
186			}
187		}
188		// 用原编号重放：load 先于幂等重放执行，两个原请求都不能把第一条投料
189		// 当成自己的登记返回。
190		for _, reqNo := range []string{"feed-1", "feed-2"} {
191			if _, err := s.AddFeeding(reqNo, "B1", "M1", "1.000", tm, "张三"); !errors.Is(err, ErrCorruptData) {
192				t.Fatalf("重放请求 %q 应先在重新读取时返回 ErrCorruptData，得到 %v", reqNo, err)
193			}
194		}
195		// 对正常批次 B2 的幂等重放与新写入同样不能绕过。
196		if _, err := s.AddFeeding("feed-b2", "B2", "M1", "1.000", tm, "张三"); !errors.Is(err, ErrCorruptData) {
197			t.Fatalf("损坏台账上重放正常批次的请求应返回 ErrCorruptData，得到 %v", err)
198		}
199		if _, err := s.AddFeeding("feed-x", "B2", "M1", "1.000", tm, "钱七"); !errors.Is(err, ErrCorruptData) {
200			t.Fatalf("损坏台账上写入正常批次应返回 ErrCorruptData，得到 %v", err)
201		}
202	
203		// 被拒绝的访问不改动文件，新写入不留下请求记录。
204		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
205		if err != nil {
206			t.Fatal(err)
207		}
208		if !bytes.Equal(after, bad) {
209			t.Fatalf("被拒绝的访问不应改动台账文件")
210		}
211		if bytes.Contains(after, []byte("feed-x")) {
212			t.Fatalf("被拒绝的写入不应留下请求记录或占用请求编号")
213		}
214	
215		// 恢复原文件后：两个原请求各自取回自己第一次成功的记录（序号 1、2），
216		// 批次中两条投料都在；被拒绝过的新编号 feed-x 仍可提交，取得新序号。
217		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
218			t.Fatal(err)
219		}
220		r1, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三")
221		if err != nil {
222			t.Fatalf("恢复后重放 feed-1 失败: %v", err)
223		}
224		checkFeedingView(t, r1, 1, "M1", "1", tm, "张三")
225		r2, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", tm, "张三")
226		if err != nil {
227			t.Fatalf("恢复后重放 feed-2 失败: %v", err)
228		}
229		checkFeedingView(t, r2, 2, "M1", "1", tm, "张三")
230		view, err := s.GetBatch("B1")
231		if err != nil {
232			t.Fatal(err)
233		}
234		if len(view.Feedings) != 2 {
235			t.Fatalf("恢复后 B1 应为 2 条投料，得到 %d 条", len(view.Feedings))
236		}
237		// 换一个未使用的请求编号提交相同投料内容，仍是新的一次投料：取得
238		// 连续序号 3，并计入实投量（M1 累计 3 克）。
239		r3, err := s.AddFeeding("feed-x", "B1", "M1", "1.000", tm, "张三")
240		if err != nil {
241			t.Fatalf("被拒绝过的请求编号恢复后应可正常使用: %v", err)
242		}
243		checkFeedingView(t, r3, 3, "M1", "1", tm, "张三")
244		view, err = s.GetBatch("B1")
245		if err != nil {
246			t.Fatal(err)
247		}
248		if len(view.Feedings) != 3 {
249			t.Fatalf("新编号相同内容应产生新投料，B1 应为 3 条，得到 %d 条", len(view.Feedings))
250		}
251		if got := view.Materials[0].ActualGrams; got != "3" {
252			t.Fatalf("三条各 1 克投料后 M1 累计实投应为 3 克，得到 %q", got)
253		}
254	}
255	
256	// 不同批次可以各有序号为 1 的投料：即使投料内容完全相同，只要每个请求
257	// 指向各自批次的登记，就不是重复指向。正常台账必须可以打开、重放与查询。
258	func TestSameFeedingSeqInDifferentBatchesIsNotAliasing(t *testing.T) {
259		dir := t.TempDir()
260		setupFeedingAliasLedger(t, dir)
261		tm := feedingAliasBaseTime()
262	
263		s, err := Open(dir)
264		if err != nil {
265			t.Fatalf("不同批次各自序号 1 的正常台账应能打开: %v", err)
266		}
267		defer s.Close()
268	
269		r1, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三")
270		if err != nil {
271			t.Fatalf("重放 feed-1 失败: %v", err)
272		}
273		checkFeedingView(t, r1, 1, "M1", "1", tm, "张三")
274		rb2, err := s.AddFeeding("feed-b2", "B2", "M1", "1.000", tm, "张三")
275		if err != nil {
276			t.Fatalf("重放 feed-b2 失败: %v", err)
277		}
278		// B2 的序号 1 与 B1 的序号 1 互不影响。
279		checkFeedingView(t, rb2, 1, "M1", "1", tm, "张三")
280		b2, err := s.GetBatch("B2")
281		if err != nil {
282			t.Fatal(err)
283		}
284		if len(b2.Feedings) != 1 || b2.Feedings[0].Seq != 1 {
285			t.Fatalf("B2 应只有自己的序号 1 投料，得到 %+v", b2.Feedings)
286		}
287	}
288	
289	// 批次关闭后，保存的投料请求仍受这项规则约束：B1 关闭后再把 feed-2 的
290	// 结果序号改成 1，打开台账仍必须以 ErrCorruptData 拒绝，关闭结果本身
291	// 完整也不能放行。
292	func TestAliasingRejectedEvenWhenBatchClosed(t *testing.T) {
293		dir := t.TempDir()
294		// 先建与 setupFeedingAliasLedger 相同的台账，但 B1 在两次投料后关闭。
295		s, err := Open(dir)
296		if err != nil {
297			t.Fatal(err)
298		}
299		registerStandardRecipe(t, s, "recipe-1")
300		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
301			t.Fatal(err)
302		}
303		if _, err := s.StartBatch("s1", "B1"); err != nil {
304			t.Fatal(err)
305		}
306		tm := feedingAliasBaseTime()
307		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三"); err != nil {
308			t.Fatal(err)
309		}
310		if _, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", tm, "张三"); err != nil {
311			t.Fatal(err)
312		}
313		if _, err := s.CloseBatch("close-1", "B1"); err != nil {
314			t.Fatal(err)
315		}
316		if err := s.Close(); err != nil {
317			t.Fatal(err)
318		}
319		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
320		if err != nil {
321			t.Fatal(err)
322		}
323		bad := aliasFeedingResultToFirst(t, good)
324		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
325			t.Fatal(err)
326		}
327	
328		s2, err := Open(dir)
329		if !errors.Is(err, ErrCorruptData) {
330			t.Fatalf("关闭批次的两个投料请求指向同一条投料也应返回 ErrCorruptData，得到 %v", err)
331		}
332		if s2 != nil {
333			s2.Close()
334			t.Fatalf("损坏台账不应返回可用的 Store 对象")
335		}
336		msg := err.Error()
337		for _, want := range []string{"feed-1", "feed-2", "B1", "登记序号 1"} {
338			if !strings.Contains(msg, want) {
339				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
340			}
341		}
342		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
343		if err != nil {
344			t.Fatal(err)
345		}
346		if !bytes.Equal(got, bad) {
347			t.Fatalf("拒绝打开不应改动台账文件")
348		}
349	}
350	
351	// 已有投料没有对应请求记录时沿用现有读取规则：删除 feed-2 的请求记录后，
352	// B1 序号 2 的投料仍然保留、计入实投量，打开与查询正常，不要求补造请求。
353	// 跨请求核对只约束“请求之间不能指向同一条投料”，不要求每条投料都有请求。
354	func TestFeedingWithoutRequestRecordStillReadable(t *testing.T) {
355		dir := t.TempDir()
356		good := setupFeedingAliasLedger(t, dir)
357		tm := feedingAliasBaseTime()
358	
359		var st persistedState
360		if err := json.Unmarshal(good, &st); err != nil {
361			t.Fatal(err)
362		}
363		delete(st.Requests, "feed-2")
364		data, err := json.MarshalIndent(&st, "", "  ")
365		if err != nil {
366			t.Fatal(err)
367		}
368		if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
369			t.Fatal(err)
370		}
371	
372		s, err := Open(dir)
373		if err != nil {
374			t.Fatalf("投料缺少对应请求记录不应判为损坏: %v", err)
375		}
376		defer s.Close()
377	
378		view, err := s.GetBatch("B1")
379		if err != nil {
380			t.Fatal(err)
381		}
382		if len(view.Feedings) != 2 {
383			t.Fatalf("删除请求记录不应删除投料，B1 应仍为 2 条，得到 %d 条", len(view.Feedings))
384		}
385		checkFeedingView(t, &view.Feedings[0], 1, "M1", "1", tm, "张三")
386		checkFeedingView(t, &view.Feedings[1], 2, "M1", "1", tm, "张三")
387		if got := view.Materials[0].ActualGrams; got != "2" {
388			t.Fatalf("无请求记录的投料仍应计入实投量，M1 累计应为 2 克，得到 %q", got)
389		}
390		// feed-1 的幂等重放不受影响，仍取回序号 1；用未使用编号提交相同内容
391		// 仍是新的一次投料（序号 3）。
392		r1, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三")
393		if err != nil {
394			t.Fatalf("feed-1 重放应成功: %v", err)
395		}
396		checkFeedingView(t, r1, 1, "M1", "1", tm, "张三")
397	}
