// validateCreateBatchRequestTargets 在逐条创建请求核对都通过后，再做跨请求的
// 批次唯一性核对：两个不同的成功创建批次请求，原提交不能指向同一个批次编号。
// 每个请求单独看都可能满足“保存结果、原提交内容与数量核对逐项一致”，但若
// 同一个批次编号同时被两个请求编号的创建请求认领，这两个请求就不可能各自
// 对应一次成功的首次创建——批次只有一条记录、创建结果各自合法也不改变这一
// 点，重放任一请求都不应把另一次保存当成该请求自己的首次创建返回。
//
// 指向按“原提交内容中的批次编号”认定：逐条核对已经保证提交内容可解析、
// 对应批次存在、保存结果与该提交选定的配方版本及份数一致，这里不再重复
// 这些检查，只判断同一批次编号是否被两个不同请求编号的创建请求同时指向。
// 认定只看原提交，不看批次现状：批次后来调整了配方与份数、开始执行、投料
// 并关闭，都不影响这份创建记录的合法性，也不能拿批次现在的计划筛掉早期
// 请求来掩盖重复创建。两份提交完全相同（同一配方版本与份数）属于重复；
// 两份提交采用不同配方版本或份数、各自保存结果仍符合对应提交时，同样不能
// 解释成两次合法创建。不同批次各自的创建请求互不影响（即使选用同一配方
// 版本与份数）；草稿调整、开始执行与关闭请求引用同一批次属于正常操作，
// 不参与本核对。
//
// 一旦发现两个不同的创建请求指向同一批次编号，整份台账即视为损坏：不能
// 任选一份请求保留后继续，不能合并两份记录、不能给批次改号，也不能重新
// 创建批次来消除矛盾。该检查覆盖所有已保存的创建批次请求，台账里另有
// 正常批次、或本次只查询/写入别的正常记录，都不能绕过。核对只读取现有
// 记录，绝不改动台账文件。
func validateCreateBatchRequestTargets(st *persistedState) error {
	// owners 按批次编号记录第一个指向它的创建请求；同一请求编号在台账中
	// 只有一条请求记录（Requests 以请求编号为键），因此同一批次编号的
	// 第二次出现必然来自另一个不同的请求编号。请求记录按请求编号排序后
	// 遍历，保证同一份损坏台账无论 map 的遍历顺序如何，报错中先出现的
	// 都是编号较小的那个请求，错误信息稳定、可核对。
	reqNos := make([]string, 0, len(st.Requests))
	for reqNo, req := range st.Requests {
		if req.Op == opCreateBatch {
			reqNos = append(reqNos, reqNo)
		}
	}
	sort.Strings(reqNos)
	owners := make(map[string]string)
	for _, reqNo := range reqNos {
		req := st.Requests[reqNo]
		var payload createBatchPayload
		if err := json.Unmarshal([]byte(req.Payload), &payload); err != nil {
			// 逐条核对（validateCreateBatchRequests）先于本检查执行，走到这里
			// 提交内容必然可解析；防御性处理，保持损坏分类。
			return fmt.Errorf("%w: 创建批次请求 %q 保存的提交内容无法解析",
				ErrCorruptData, reqNo)
		}
		if first, ok := owners[payload.BatchNo]; ok {
			return fmt.Errorf("%w: 创建批次请求 %q 与 %q 的原提交都指向批次 %q：同一批次不能保存两个成功的创建请求，即使两份提交完全相同、各自保存结果都是合法的草稿结果且数量核对一致，也不能解释成两次合法创建；不能挑选其中一份保留、合并两份记录、给批次改号或重新创建批次来消除矛盾",
				ErrCorruptData, first, reqNo, payload.BatchNo)
		}
		owners[payload.BatchNo] = reqNo
	}
	return nil
}

